@Component("laboratoryOrder-handler")
@ProcessingGroup("laboratoryOrder-processing-group")
public class LaboratoryOrderEventHandler {
	
	// core constructor
	LaboratoryOrderEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateLaboratoryOrderEvent
     */
    @EventHandler
    public void handle( CreateLaboratoryOrderEvent event) {
        entityManager.persist(new LaboratoryOrder(event.getLaboratoryOrderId(), event.getTestCode(), event.getFastingRequired(), event.getOrder(), event.getLaboratory(), event.getResults(), event.getSpecimenType()));
    }

    /*
     * @param	event UpdateLaboratoryOrderEvent
     */
    @EventHandler
    public LaboratoryOrder handle( UpdateLaboratoryOrderEvent event) {
    	entityManager.merge(new LaboratoryOrder(event.getLaboratoryOrderId(), event.getTestCode(), event.getFastingRequired(), event.getOrder(), event.getLaboratory(), event.getResults(), event.getSpecimenType()));
    }
    
    /*
     * @param	event DeleteLaboratoryOrderEvent
     */
    @EventHandler
    public void on( DeleteLaboratoryOrderEvent event) {
    	LaboratoryOrder entity = new LaboratoryOrder();
   
    	// ------------------------------------------
    	// apply the LaboratoryOrderId
    	// ------------------------------------------
    	entity.setLaboratoryOrderId( event.getLaboratoryOrderId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final LaboratoryOrderRepository laboratoryOrderEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(LaboratoryOrderEventHandler.class.getName());

}
